// Filtrează și transformă rezultatele SEAP
// Coduri CPV IT: 72xxxxxx
const IT_CPV_PREFIXES = ['72', '48', '30'];

const results = $input.all();
const tenders = [];

for (const result of results) {
  const data = result.json;
  const items = data.items || [];

  for (const item of items) {
    // Extrage codul CPV
    const cpvMatch = item.cpvCodeAndName?.match(/^(\d+)/);
    const cpvCode = cpvMatch ? cpvMatch[1] : '';
    const cpvPrefix = cpvCode.substring(0, 2);

    // Filtrează doar licitații IT
    if (!IT_CPV_PREFIXES.includes(cpvPrefix)) {
      continue;
    }

    // Verifică dacă are deadline în viitor
    if (item.tenderReceiptDeadlineExport) {
      const deadline = new Date(item.tenderReceiptDeadlineExport);
      if (deadline < new Date()) {
        continue; // Skip expirate
      }
    }

    // Verifică statusul - doar publicate, nu atribuite
    const state = item.sysProcedureState?.text || '';
    if (state.toLowerCase().includes('atribuita') || state.toLowerCase().includes('anulat')) {
      continue;
    }

    tenders.push({
      json: {
        seapId: String(item.caNoticeId || item.noticeNo),
        title: item.contractTitle || 'Fără titlu',
        description: item.shortDescription || item.contractTitle,
        contractingAuth: item.contractingAuthorityNameAndFN || 'Necunoscut',
        contractingAuthCui: item.contractingAuthorityNameAndFN?.match(/^(\d+)/)?.[1],
        estimatedValue: item.ronContractValue || null,
        currency: 'RON',
        cpvCode: cpvCode + (item.cpvCodeAndName?.includes('-') ? '-' + item.cpvCodeAndName.split('-')[1]?.split(' ')[0] : ''),
        cpvDescription: item.cpvCodeAndName,
        procedureType: item.sysProcedureType?.text || 'unknown',
        contractType: item.sysAcquisitionContractType?.text || item.sysContractAssigmentType?.text,
        publicationDate: item.noticeStateDate || new Date().toISOString(),
        submissionDeadline: item.tenderReceiptDeadlineExport || null,
        seapUrl: `https://e-licitatie.ro/pub/notices/c-notice/v2/view/${item.caNoticeId}`
      }
    });
  }
}

// Deduplică
const seen = new Set();
const unique = tenders.filter(t => {
  if (seen.has(t.json.seapId)) return false;
  seen.add(t.json.seapId);
  return true;
});

console.log(`Found ${unique.length} IT tenders`);

return unique.length > 0 ? unique : [{ json: { noResults: true, message: 'Nu s-au găsit licitații IT noi' } }];
